import math

def is_perfect_square(num):
    if num < 0:
        return False
    sqrt_num = int(math.isqrt(num))
    return sqrt_num * sqrt_num == num

start_n = 45
end_n = 90 # Check up to 89, so 90 exclusive is fine

smallest_n = None
for n in range(start_n, end_n):
    D = 24084 - 3 * (n**2)
    if is_perfect_square(D):
        smallest_n = n
        break

if smallest_n is not None:
    print(f"The smallest n >= 45 is: {smallest_n}")
else:
    print("No such n found in the range [45, 89].")
